internal static int RunManifest(string[] a){if(a.Length!=4)return 2;try{var png=File.ReadAllBytes(a[1]);var source=Path.GetFullPath(a[2]);var output=Path.GetFullPath(a[3]);Directory.CreateDirectory(output);var original=File.ReadAllText(Path.Combine(source,"runtime-manifest.json"));var cases=new[]{new C("architecture","\"EfficientNet-B0\"","\"WrongNet\""),new C("preprocessing_version","\"H1D9D1C-PILLOW-12.3.0-BICUBIC-FIXED22\"","\"WRONG\""),new C("class_mapping","\"0\": \"NO_FACTURA\", \"1\": \"FACTURA\"","\"0\": \"FACTURA\", \"1\": \"NO_FACTURA\""),new C("threshold","0.1169927716255188","0.2169927716255188"),new C("external_data","\"external_data\": false","\"external_data\": true")};var lines=new List<string>();var ok=true;foreach(var q in cases){var dir=Path.Combine(Path.GetTempPath(),"H1D9E1-contract-"+q.Name+"-"+Guid.NewGuid().ToString("N"));try{Directory.CreateDirectory(dir);File.Copy(Path.Combine(source,"candidate.onnx"),Path.Combine(dir,"candidate.onnx"));var changed=original.Replace(q.From,q.To);if(changed==original)throw new InvalidDataException("No se pudo corromper "+q.Name);File.WriteAllText(Path.Combine(dir,"runtime-manifest.json"),changed,new UTF8Encoding(false));var r=VisualInvoiceShadowService.EvaluateCanonicalPngForValidation(png,dir);var pass=r.Status=="ERROR"&&r.ErrorCode=="CONTRACT_INVALID";ok&=pass;lines.Add("- "+q.Name+": `"+r.Status+" / "+r.ErrorCode+"`; sesión creada: no; aprobado: "+pass+".");}finally{if(Directory.Exists(dir))Directory.Delete(dir,true);}}File.WriteAllText(Path.Combine(output,"manifest-contract-validation.md"),"# Contrato completo del manifest\n\n"+string.Join("\n",lines)+"\n\n- Sesiones ONNX creadas durante corrupciones: "+VisualInvoiceShadowService.SessionsCreated+".\n- Modelo original modificado: no.\n",new UTF8Encoding(false));return ok&&VisualInvoiceShadowService.SessionsCreated==0?0:1;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
static List<Dictionary<string,string>>Read(string p){var z=new List<Dictionary<string,string>>();using(var q=new TextFieldParser(p,Encoding.UTF8)){q.SetDelimiters(",");q.HasFieldsEnclosedInQuotes=true;var h=q.ReadFields();while(!q.EndOfData){var f=q.ReadFields();var r=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);for(int i=0;i<h.Length;i++)r[h[i]]=f[i];z.Add(r);}}return z;}static string Mime(string p){var x=Path.GetExtension(p).ToLowerInvariant();return x==".pdf"?"application/pdf":x==".png"?"image/png":"image/jpeg";}static string B(bool x){return x?"true":"false";}static string Csv(params string[]x){return string.Join(",",x.Select(v=>"\""+(v??"").Replace("\"","\"\"")+"\""));}sealed class C{public C(string n,string f,string t){Name=n;From=f;To=t;}public string Name,From,To;}
